<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class PrintReportController extends Controller{
 public function group(Request $r,$group){$p=$r->attributes->get('academic_period');$g=DB::table('study_groups')->find($group);abort_if(!$p||!$g,404);$mq=DB::table('student_group_memberships as m')->join('students as s','s.id','=','m.student_id')->where('m.academic_period_id',$p->id)->where('m.study_group_id',$group)->where('m.status','active');$students=$mq->exists()?$mq->select('s.*')->orderBy('s.last_name')->get():DB::table('students')->where('current_group_id',$group)->where('status','active')->orderBy('last_name')->get();foreach($students as $s){$base=DB::table('lesson_occurrences as l')->where('l.academic_period_id',$p->id)->where('l.study_group_id',$group);$ids=(clone $base)->pluck('id');$s->avg=DB::table('grade_records')->whereIn('lesson_occurrence_id',$ids)->where('student_id',$s->id)->whereIn('value',['2','3','4','5'])->avg(DB::raw('CAST(value AS REAL)'));$aq=DB::table('attendance_records')->whereIn('lesson_occurrence_id',$ids)->where('student_id',$s->id);$s->absent=(clone $aq)->where('status','absent')->count();$s->sick=(clone $aq)->where('status','sick')->count();$s->excused=(clone $aq)->where('status','excused')->count();$s->late=(clone $aq)->where('status','late')->count();$marked=(clone $aq)->count();$present=(clone $aq)->whereIn('status',['present','late'])->count();$s->pct=$marked?round($present*100/$marked):null;}return view('reports.print-group',compact('p','g','students'));}
}